#include <atomic>
#include <mutex>

struct Config { int timeout_ms; };
std::atomic<Config*> g_config{nullptr};
std::mutex g_init_mtx;

Config* get_config() {
    Config* cfg = g_config.load(std::memory_order_acquire);
    if (!cfg) {
        std::lock_guard<std::mutex> lk(g_init_mtx);
        cfg = g_config.load(std::memory_order_relaxed);
        if (!cfg) {
            cfg = new Config{250};
            g_config.store(cfg, std::memory_order_release); // Publishes initialized fields
        }
    }
    return cfg;
}
